const u="__other__",f=["#1976d2","#388e3c","#f57c00","#7b1fa2","#d32f2f","#00796b","#5c6bc0","#e91e63","#00bcd4","#ff9800"],i={USD:"$",CNY:"¥",HKD:"HK$",EUR:"€",GBP:"£",JPY:"¥",KRW:"₩"};function n(t="CNY"){return i[t]||t}function o(t,e="CNY"){return`${n(e)}${t.toLocaleString("zh-CN",{minimumFractionDigits:2,maximumFractionDigits:2})}`}function c(t,e="CNY"){const r=n(e);return t>=1e8?`${r}${(t/1e8).toFixed(1)}亿`:t>=1e4?`${r}${(t/1e4).toFixed(1)}万`:t>=1e3?`${r}${(t/1e3).toFixed(1)}k`:o(t,e)}function m(t){return t>=1e8?`${(t/1e8).toFixed(1)}亿`:t>=1e4?`${(t/1e4).toFixed(1)}万`:t>=1e3?`${(t/1e3).toFixed(1)}k`:t.toFixed(0)}function $(t){if(/^\d{4}-\d{2}$/.test(t)){const[e,r]=t.split("-");return`${e.slice(2)}年${Number(r)}月`}if(/^\d{4}-\d{2}-\d{2}$/.test(t)){const[,e,r]=t.split("-");return`${Number(e)}月${Number(r)}日`}return t}export{f as BILL_CHART_COLORS,u as OTHER_KEY,n as currencySymbol,o as formatCurrency,c as formatCurrencyShort,$ as formatDateTick,m as formatShortNumber};
